// The range of `table` holding `c`, the tables are sorted and disjoint.
fn find(table: &[(u32, u32)], c: char) -> Option<usize> {
    use core::cmp::Ordering::*;
    let c = c as u32;
    table.binary_search_by(|&(lo, hi)| if hi < c { Less } else if lo > c { Greater } else { Equal }).ok()
}

// Character classes of Unicode 15, ASCII answers without the tables.
pub fn is_digit(c: char) -> bool { if c.is_ascii() { c.is_ascii_digit() } else { find(&DIGIT, c).is_some() } }
pub fn is_alpha(c: char) -> bool { if c.is_ascii() { c.is_ascii_alphabetic() } else { find(&ALPHA, c).is_some() } }
pub fn is_numeric(c: char) -> bool { if c.is_ascii() { c.is_ascii_digit() } else { find(&NUMERIC, c).is_some() } }
pub fn is_alnum(c: char) -> bool { is_alpha(c) || is_numeric(c) }

// Whitespace for `isspace`, `split` and `strip`, the separators 0x1C to 0x1F included.
pub fn is_space(c: char) -> bool { c.is_whitespace() || ('\x1c'..='\x1f').contains(&c) }

// The value of a decimal digit of any script.
pub fn decimal_value(c: char) -> Option<u32> {
    if c.is_ascii_digit() { return Some(c as u32 - '0' as u32); }
    find(&DECIMAL, c).map(|i| (c as u32 - DECIMAL[i].0) % 10)
}

// The titlecase of `c`, its uppercase unless the table says otherwise.
pub fn push_title(out: &mut alloc::string::String, c: char) {
    match TITLE.binary_search_by_key(&(c as u32), |&(k, _)| k) {
        Ok(i) => out.push_str(TITLE[i].1),
        Err(_) => out.extend(c.to_uppercase()),
    }
}

// A titlecase letter such as `ǅ`, neither upper nor lower but its own titlecase.
pub fn is_titlecase(c: char) -> bool {
    !c.is_lowercase() && !c.is_uppercase()
        && TITLE.binary_search_by_key(&(c as u32), |&(k, _)| k).is_ok_and(|i| TITLE[i].1.chars().eq(core::iter::once(c)))
}

// A character with case, the letters `title` capitalises and words end without.
pub fn is_cased(c: char) -> bool { c.is_uppercase() || c.is_lowercase() || is_titlecase(c) }

// Number text with spaces trimmed and decimals of any script read as ASCII digits.
pub fn number_text(s: &str) -> alloc::borrow::Cow<'_, str> {
    let t = s.trim_matches(is_space);
    if t.is_ascii() { return t.into(); }
    t.chars().map(|c| decimal_value(c).map_or(c, |d| char::from(b'0' + d as u8))).collect::<alloc::string::String>().into()
}
